/* =====================================================
   FUGA MYTHICA — ROOT_STORIES batch 9: Greek combining forms, English/German learned roots, prefixes
   ===================================================== */
delete ROOT_STORIES.alias.juven; delete ROOT_STORIES.alias.jus;
Object.assign(ROOT_STORIES.deMap, { real: "re2", phys: "phys", plan: "plan", form: "form", arithm: "arithm", geometr: "geo", just: "jur", techn: "techn", origin: "orig", maschin: "mech", experim: "per", mus: "mus", funkt: "funct", atmos: "sphere", demokrat: "dem", milit: "mil", zone: "zone", charakt: "charact", diskus: "cuss", argument: "arg", kanzl: "cancel", struk: "stru", histor: "vid" });
Object.assign(ROOT_STORIES.shared, {
  lacrim: ["lacrima(眼泪)是古拉丁语 dacruma——d 变 l(像 lingua<dingua)——印欧语 *dáḱru(泪):希腊语 dakry、英语 tear(古英语 tēar)、德语 Träne、哥特语 tagr、威尔士语 deigr。罗马人 lacrimae rerum\"万物之泪\"(维吉尔);lacrimare 流泪,lacrimosus 含泪的(lachrymose 1660 年代),lacrimal 泪腺的(lacrimal gland),Lacrimosa 是《安魂曲》的\"落泪之日\"(莫扎特绝笔段),larme 法语泪(lacrima→lairme),lacrima 意大利语(Lacryma Christi 基督之泪葡萄酒),lágrima 西班牙语,tear 是它的日耳曼亲戚。",
    "lacrima (a tear) is Old Latin dacruma — d became l, as in lingua from dingua — PIE *dáḱru (tear): Greek dakry, English tear (Old English tēar), German Träne, Gothic tagr, Welsh deigr. Virgil's lacrimae rerum, the tears of things; lacrimare to weep, lacrimosus tearful (lachrymose 1660s), lacrimal (the lacrimal gland), the Lacrimosa of the Requiem (Mozart's last lines), French larme, Italian lacrima (the wine Lacryma Christi), Spanish lágrima; tear is the Germanic cousin."],
  contra: ["contra(对面、反对)是 com-(与)加比较级 -tero-:\"相对的那一边\";同根有 con-、希腊语 无。罗马人 contra 是面对面、也是反对;contrarius 相反的(contrary 1300 年代),contra-dicere 说反话(contradict),contra-venire 违反(contravene),contra-ceptio 避孕(1886 造词),contrast 是 contra-stare 对立(经意大利语 contrastare 1690 年代),contraband 是意大利语 contra-bando 违禁(bando 法令),counter- 是 contra 经法语 contre(counter-act、encounter 是 in-contra\"迎面遇上\"!),country 是 contrata\"对面的地\"——乡村(1200 年代)!,contre 法语,contro 意大利语,contra 西班牙语,contralto 中音(与高音相对),pro and con。",
    "contra (opposite, against) is com- (with) plus the comparative -tero-: the facing side. Roman contra was face to face and in opposition; contrarius (contrary 1300s), contra-dicere to speak against (contradict), contra-venire to go against (contravene), contra-ceptio (coined 1886), contrast contra-stare, to stand against (via Italian contrastare 1690s), contraband Italian contra-bando, against the decree, counter- contra through French contre (counter-act; encounter is in-contra, to come up against!), and country is contrata, the land lying opposite (1200s)!, French contre, Italian contro, Spanish contra, contralto the voice set against the high one, pro and con."],
  castr: ["castrum(堡垒)与 castrare(切)同根——印欧语 *kes-(切):堡垒是\"切出的地\"(挖壕沟)。罗马军营 castra(复数)是每晚扎的标准营地;英国地名 -chester、-caster、-cester(Manchester、Lancaster、Worcester)都是罗马 castra!castellum 小堡——castle(1050 年代经诺曼法语 castel),château 法语城堡(Châteauneuf),castello 意大利语,castillo 西班牙语(Castilla 卡斯蒂利亚是\"城堡之地\"!),castellan 城堡主,chatelaine 女主人(腰链),Castro 姓(城堡),castrametation 扎营术。",
    "castrum (a fort) shares PIE *kes- (to cut) with castrare — a fort is ground cut off by a ditch. The legion's castra (plural) was the standard camp dug each night; English -chester, -caster and -cester (Manchester, Lancaster, Worcester) are all Roman castra!; castellum a small fort — castle (1050s through Norman French castel), French château (Châteauneuf), Italian castello, Spanish castillo (Castilla is the land of castles!), castellan the keeper, chatelaine the lady and her key-chain, Castro the surname, castrametation the art of laying out a camp."],
  tachy: ["希腊语 takhys(快)词源不明。takhos 速度;tachy-cardia 心动过速(1889),tachy-meter 转速表,tachy-graphy 速记(希腊已有,tachygraphos 速记员),tachy-on 是 1967 年假想的超光速粒子,tachi-stoscope 速示器,tacho-meter 转速计(1810 年代),Tachyglossus 针鼹\"快舌\",tachy-phylaxis 快速耐受;拉丁语 celer、velox 是另两个\"快\"。",
    "Greek takhys (swift) is of unknown origin. takhos speed; tachy-cardia a racing heart (1889), tachy-meter, tachy-graphy shorthand (a Greek trade already: the tachygraphos), tachy-on the hypothetical faster-than-light particle (1967), tachi-stoscope, tacho-meter a speed-gauge (1810s), Tachyglossus the quick-tongued echidna, tachy-phylaxis; Latin's celer and velox are its other swift words."],
  morph: ["希腊语 morphē(形)词源不明,可能与拉丁语 forma 同借自某地中海语(f/m 换位)。荷马的 morphē 是外貌;meta-morphōsis 变形(奥维德的《变形记》Metamorphoses),a-morphos 无形(amorphous),morpho-logia 是歌德 1796 年造的\"形态学\",Morpheus 是梦神(奥维德:塑造梦中形象者),morphine 是 1817 年泽尔蒂纳从 Morpheus 命名的(令人入梦),poly-morph 多形,iso-morph 同形,morpheme 语素(1896),anthropo-morphic 拟人的,endo-morph 内胚型,morphing 1990 年代电影特效。",
    "Greek morphē (shape) is of unknown origin, possibly borrowed like Latin forma from a Mediterranean tongue (with f and m swapped). Homer's morphē was outward form; meta-morphōsis a change of shape (Ovid's Metamorphoses), a-morphos shapeless (amorphous), morpho-logia Goethe's 1796 coinage, Morpheus the god of dreams (Ovid's shaper of dream-figures), morphine Sertürner's 1817 name after Morpheus (it brings sleep), poly-morph, iso-morph, morpheme (1896), anthropo-morphic, endo-morph, morphing the 1990s film effect."],
  soph: ["希腊语 sophos(有技艺、聪明)词源不明。荷马的 sophos 是巧匠;sophia 智慧(Hagia Sophia 圣智大教堂,537 年),sophistēs 是收费教修辞的\"智者\"——柏拉图把 Sophists 写成诡辩家(sophistry、sophism),philo-sophia 是毕达哥拉斯的\"爱智\"(自谦不是 sophos),sophisticated 先是\"掺假的\"(1600 年代——sophisticare 用诡辩使不纯),1890 年代转为\"世故的\",sopho-more 是\"聪明的傻瓜\"(sophos+mōros,哈佛 1680 年代),theo-sophy 神智学,pan-sophy,Sophocles 是\"智慧荣耀\",Sophie/Sofia 名字,sophomoric。",
    "Greek sophos (skilled, wise) is of unknown origin. Homer's sophos was a skilled craftsman; sophia wisdom (Hagia Sophia, Holy Wisdom, 537), sophistēs a paid teacher of rhetoric — Plato made the Sophists into quibblers (sophistry, sophism), philo-sophia Pythagoras' love of wisdom (too modest to be called sophos), sophisticated meant adulterated in the 1600s (sophisticare, to doctor by quibbling) and worldly-wise by the 1890s, sopho-more the wise fool (sophos + mōros, Harvard 1680s), theo-sophy, Sophocles wisdom-famed, Sophie and Sofia, sophomoric."],
  cosm: ["希腊语 kosmos(秩序、装饰、世界)词源不明。荷马的 kosmos 是军队的阵列和女人的首饰(kosmētikos 装饰的——cosmetic 1600 年代!);毕达哥拉斯据说第一个把有序的宇宙叫 kosmos,cosmos 1650 年代(洪堡的《宇宙》Kosmos 1845 使它流行),cosmo-logia 宇宙论(沃尔夫 1730 年代),cosmo-politēs 世界公民(第欧根尼自称;cosmopolitan 1640 年代),micro-cosmos 小宇宙(人),cosmo-naut 苏联的\"宇宙航行者\"(1959),cosmic,cosmogony 宇宙起源论,cosmetology。",
    "Greek kosmos (order, adornment, the world) is of unknown origin. Homer's kosmos was the army's array and a woman's jewellery (kosmētikos of adornment — cosmetic 1600s!); Pythagoras is said to have first called the ordered universe kosmos, cosmos 1650s (Humboldt's Kosmos of 1845 made it current), cosmo-logia (Wolff 1730s), cosmo-politēs a citizen of the world (Diogenes' self-description; cosmopolitan 1640s), micro-cosmos the little world that is man, cosmo-naut the Soviet universe-sailor (1959), cosmic, cosmogony, cosmetology."],
  therm: ["希腊语 thermos(热)来自印欧语 *gʷʰer-(热),同根有拉丁语 formus(温)、fornax(炉——furnace)、英语 warm、德语 warm、梵语 gharma(热)、亚美尼亚语 jerm。希腊的 thermai 是温泉(Thermopylae 是\"温泉关\"),罗马的 thermae 是大浴场(卡拉卡拉浴场);thermo-meter 1620 年代(法语 thermomètre),thermo-dynamics 汤姆森 1849,thermos 是 1904 年德国的保温瓶商标,thermo-stat 1830 年代,iso-therm 等温线(洪堡 1817),hypo-thermia,thermal 1750 年代,endo-thermic,thermite 铝热剂(1900),furnace 与 warm 是它的拉丁与日耳曼亲戚。",
    "Greek thermos (hot) comes from PIE *gʷʰer- (hot), shared with Latin formus (warm), fornax (an oven — furnace), English warm, German warm, Sanskrit gharma (heat), Armenian jerm. Greek thermai were hot springs (Thermopylae, the hot gates), Roman thermae the great baths (of Caracalla); thermo-meter 1620s (French thermomètre), thermo-dynamics Thomson 1849, Thermos the 1904 German flask trade name, thermo-stat 1830s, iso-therm (Humboldt 1817), hypo-thermia, thermal 1750s, endo-thermic, thermite (1900); furnace and warm are its Latin and Germanic cousins."],
  dyn: ["希腊语 dynamis(力、能力)来自 dynasthai(能够),词源不明。亚里士多德的 dynamis 是\"潜能\"(与 energeia 现实相对);dynastēs 掌权者——dynasty 王朝(1400 年代),dynamikos 有力的(dynamic 1810 年代经法语),dynamite 是诺贝尔 1867 年的命名,dynamo 是西门子 1867 年的\"发电机\"(dynamo-electric machine),dyne 力的单位(1873),aero-dynamics,thermo-dynamics,dynamism,dynast,Dinamo 是苏联体育协会(1923)。",
    "Greek dynamis (power, ability) comes from dynasthai (to be able), of unknown origin. Aristotle's dynamis is potentiality (against energeia, actuality); dynastēs a holder of power — dynasty (1400s), dynamikos powerful (dynamic 1810s via French), dynamite Nobel's 1867 name, dynamo Siemens' 1867 dynamo-electric machine, the dyne unit of force (1873), aero-dynamics, thermo-dynamics, dynamism, dynast, Dinamo the Soviet sports society (1923)."],
  mania: ["希腊语 mania(疯狂)来自 mainesthai(发狂),印欧语 *men-(想)——与 mens、mind、memory 同根:疯是\"心\"的过度。柏拉图《斐德罗篇》分四种神圣的 mania(预言、秘仪、诗、爱);mantis 是先知(praying mantis 祈祷的\"先知\"),maenads 是狂女,mania 在英语 1400 年代是医学的\"躁狂\",-mania 作后缀 19 世纪爆发:klepto-mania 1830,mono-mania,mega-lo-mania 1890,Beatle-mania 1963,maniac 1600 年代,manic 1902,manie 法语,manía 西班牙语(也指\"癖好\")。",
    "Greek mania (madness) comes from mainesthai (to rage), PIE *men- (to think) — one root with mens, mind, memory: madness is mind in excess. Plato's Phaedrus names four divine manias (prophecy, mystery-rites, poetry, love); a mantis is a seer (the praying mantis), maenads the frenzied women, mania in English was the physician's frenzy in the 1400s, and -mania as a suffix boomed in the 19th century: klepto-mania 1830, mono-mania, megalo-mania 1890, Beatle-mania 1963, maniac 1600s, manic 1902, French manie, Spanish manía (also a quirk)."],
  eu: ["希腊语 eu(好)是 eus(好的)的中性副词,印欧语 *h₁su-(好),同根有梵语 su-(su-asti 幸福——swastika 万字!)、阿维斯陀语 hu-、古爱尔兰语 su-。eu-angelion 好消息(evangel、gospel 是它的英译 gōd-spel),eu-phōnia 好声(euphony),eu-logia 好话(eulogy),eu-thanasia 好死,eu-genēs 出身好(Eugene;eugenics 高尔顿 1883),eu-phoria 好带,eu-charistia 感恩(Eucharist),Eu-kleidēs 欧几里得\"好名声\",eu-kalyptos 桉树\"盖得好\"(花蕾),eu-phēmismos 说好话——委婉语,eu-topia 好地方(莫尔的双关),eu-tropic,Eu-rope 无关(存疑)。",
    "Greek eu (well) is the neuter adverb of eus (good), PIE *h₁su- (good), shared with Sanskrit su- (su-asti well-being — the swastika!), Avestan hu-, Old Irish su-. eu-angelion the good news (evangel; gospel is its English calque gōd-spel), eu-phōnia (euphony), eu-logia good words (eulogy), eu-thanasia a good death, eu-genēs well-born (Eugene; eugenics Galton 1883), eu-phoria, eu-charistia thanksgiving (the Eucharist), Eu-kleidēs Euclid the well-famed, eu-kalyptos the well-covered bud, eu-phēmismos speaking well — euphemism, eu-topia More's pun; Europe is unrelated (disputed)."],
  less: ["-less 是古英语 -lēas(没有的)——来自 lēas\"松、空、假\"(loose 是它的北欧同源词!,德语 los、-los,哥特语 laus,印欧语 *leu-(松开,与拉丁语 luere、solvere 同根))。古英语已有 sāwol-lēas 无魂、slǣp-lēas 无眠;-less 可以接任何名词:hopeless、endless、fearless、homeless(1610 年代),也可接动词(tireless、relentless),-losigkeit 是德语的对应(Arbeitslosigkeit 失业),less(更少)是另一个词(lǣssa),unless 与此无关(on lesse)。",
    "-less is Old English -lēas (free of) — from lēas, loose, empty, false (loose is its Norse cousin!, German los and -los, Gothic laus, PIE *leu- (to loosen, kin to Latin luere, solvere)). Old English already had sāwol-lēas soulless, slǣp-lēas sleepless; -less attaches to any noun: hopeless, endless, fearless, homeless (1610s), and to verbs (tireless, relentless); German -losigkeit answers it (Arbeitslosigkeit unemployment); less (fewer) is a different word (lǣssa), and unless is on lesse."],
  ful: ["-ful 是古英语 full(满的)作后缀——印欧语 *pl̥h₁-nós(满),与拉丁语 plenus、希腊语 plērēs、梵语 pūrṇa、德语 voll、哥特语 fulls 同一个词。古英语 wundor-full 奇妙的、sorg-full 忧愁的;-ful 造形容词(careful、beautiful 1520 年代、useful),也造量词(handful、spoonful——古英语 handfull 已有),德语 -voll(liebevoll),full 与 fill 同根,plenty 是它的拉丁亲戚。",
    "-ful is Old English full (full) used as a suffix — PIE *pl̥h₁-nós (full), one word with Latin plenus, Greek plērēs, Sanskrit pūrṇa, German voll, Gothic fulls. Old English wundor-full wonderful, sorg-full sorrowful; -ful makes adjectives (careful, beautiful 1520s, useful) and measures (handful, spoonful — Old English handfull already), German -voll (liebevoll), full is kin to fill, and plenty is its Latin cousin."],
  agog: ["希腊语 agein(引导、驱赶)来自印欧语 *h₂eǵ-(驱动),与拉丁语 agere 同根;agōgos 引导者:paid-agōgos 是领孩子上学的奴隶(pedagogue),dēm-agōgos 领导民众者,syn-agōgē 聚集(synagogue 犹太会堂——七十士译本),anagōgē 上引(anagogical 神秘解经),agōn 竞赛(agony 是竞赛的挣扎,antagonist 对手,protagonist 第一竞赛者),strat-ēgos 领军者(strategy),chor-agus 歌队指导,hypn-agogic 催眠的,mystagogue 秘仪导师,agenda 是拉丁线\"该做的事\"。",
    "Greek agein (to lead, drive) comes from PIE *h₂eǵ- (to drive), one root with Latin agere; agōgos a leader: paid-agōgos the slave who led boys to school (pedagogue), dēm-agōgos a leader of the people, syn-agōgē a gathering (synagogue, in the Septuagint), anagōgē the upward lead (the anagogical sense of scripture), agōn a contest (agony is the contestant's struggle, antagonist the opponent, protagonist the first contender), strat-ēgos an army-leader (strategy), chor-agus the chorus-master, hypn-agogic, mystagogue; agenda is the Latin line's things to be done."],
  chrom: ["希腊语 khrōma(皮肤、颜色)来自 khrōs(皮肤、表面),印欧语 *gʰreh₁-(擦)存疑——颜色是\"涂在表面的\"。khrōma 在希腊音乐里是\"半音的\"(chromatic 1590 年代——半音阶\"着色\"),chromium 是沃克兰 1797 年发现的\"多彩\"金属(化合物颜色多),chromo-some 是\"染色体\"(1888 瓦尔代尔——易被染色),chromato-graphy 色谱法(茨维特 1906),mono-chrome 单色,poly-chrome,Kodachrome 1935,chromatin 染色质,achromatic 消色差,chrome 电镀(1900 年代),chromo 彩色石印。",
    "Greek khrōma (skin, colour) comes from khrōs (skin, surface), PIE *gʰreh₁- (to rub) possible — colour is what is rubbed on a surface. In Greek music khrōma was the half-tone scale (chromatic 1590s — the coloured scale), chromium Vauquelin's 1797 metal of many-coloured compounds, chromo-some the stainable body (Waldeyer 1888), chromato-graphy (Tsvet 1906), mono-chrome, poly-chrome, Kodachrome 1935, chromatin, achromatic, chrome plating (1900s), chromo the colour print."],
  gastr: ["希腊语 gastēr(肚子,属格 gastros)可能是 *graster 异化——来自 grān(啃)。gastēr 是荷马的肚子(\"可恨的肚子\"逼奥德修斯吃饭);gastr-itis 胃炎(1806),gastro-nomia 是 1801 年贝舒的诗题\"肚子的法则\"——美食学,gastro-enterology,gastro-pod 腹足类(蜗牛,1826),gastric 1650 年代,gastrula 原肠胚(海克尔 1872),epi-gastrium 上腹,gastro-pub 1991,gaster 西班牙语?否,gastar 花费无关(vastare)。",
    "Greek gastēr (belly, genitive gastros) may be a dissimilated *graster, from grān (to gnaw). gastēr is Homer's belly (the hateful belly that makes Odysseus eat); gastr-itis (1806), gastro-nomia the title of Berchoux's 1801 poem, the belly's law — gastronomy, gastro-enterology, gastro-pod the belly-footed snail (1826), gastric 1650s, gastrula (Haeckel 1872), epi-gastrium, gastro-pub 1991."],
  iatr: ["希腊语 iatros(医生)来自 iasthai(治愈),词源不明。希波克拉底是 iatros;iatrikē 医术,psych-iatria 是赖尔 1808 年造的\"灵魂治疗\"(psychiatry),paed-iatrics 儿科(1880 年代),ger-iatrics 老年医学(纳舍尔 1909),pod-iatry 足科,iatro-genic 医源性的(1924——由治疗引起的病),phys-iatrics 物理治疗,iatro-chemistry 帕拉塞尔苏斯的医化学,archiater 御医(arch-iatros——德语 Arzt 医生就是它!)。",
    "Greek iatros (a physician) comes from iasthai (to heal), of unknown origin. Hippocrates was an iatros; iatrikē the healing art, psych-iatria Reil's 1808 soul-healing (psychiatry), paed-iatrics (1880s), ger-iatrics (Nascher 1909), pod-iatry, iatro-genic caused by treatment (1924), phys-iatrics, iatro-chemistry Paracelsus' medicine, archiater the chief physician (arch-iatros — German Arzt, doctor, is this word!)."],
  kilo: ["kilo- 是 1795 年法国公制委员会从希腊语 khilioi(千)造的前缀(kilogramme、kilomètre),印欧语 *ǵʰeslo-(千)——与拉丁语 mille 同根(*smī-ǵʰslī\"一千\")、梵语 sahasra。委员会用希腊语造倍数(kilo、hecto、deca)、拉丁语造分数(milli、centi、deci)。kilo 独用指公斤(1870 年代),kilowatt 1884,kilobyte 1960 年代(2¹⁰=1024 的\"千\"),kilohertz,kilocalorie,chiliasm 千禧年说是同一个 khilioi。",
    "kilo- was coined in 1795 by the French metric commission from Greek khilioi (a thousand) (kilogramme, kilomètre), PIE *ǵʰeslo- (thousand) — kin to Latin mille (*smī-ǵʰslī, one thousand), Sanskrit sahasra. The commission took Greek for multiples (kilo, hecto, deca) and Latin for fractions (milli, centi, deci). kilo alone is the kilogram (1870s), kilowatt 1884, kilobyte 1960s (2¹⁰ = 1024 passing for a thousand), kilohertz, kilocalorie; chiliasm, the doctrine of the thousand-year reign, is the same khilioi."],
  orth: ["希腊语 orthos(直、正)来自印欧语 *h₃erdʰ-(直立),与梵语 ūrdhva(向上)、拉丁语 arduus(陡)同根。ortho-doxos 正确意见(orthodox——东正教自称正统,1054 年分裂后),ortho-graphia 正写法(orthography 1400 年代),ortho-paedia 是安德里 1741 年造的\"正孩子\"——矫正儿童畸形(orthopaedics),ortho-dontia 正畸(1849),ortho-gonal 直角的,ortho-ptera 直翅目,ortho-clase 正长石,orthopraxy 正行,orthosis 矫形器,Orthodox Church。",
    "Greek orthos (straight, right) comes from PIE *h₃erdʰ- (upright), kin to Sanskrit ūrdhva (upward) and Latin arduus (steep). ortho-doxos of right opinion (orthodox — the Eastern Church's name for itself after 1054), ortho-graphia right writing (orthography 1400s), ortho-paedia Andry's 1741 straight-child, the correcting of children's deformities (orthopaedics), ortho-dontia (1849), ortho-gonal right-angled, ortho-ptera the straight-winged insects, ortho-clase the feldspar, orthopraxy, orthosis a brace."],
  plast: ["希腊语 plassein(捏塑)来自印欧语 *pelh₂-(铺开、平)存疑,与拉丁语 planus 可能同根。plastikos 可塑的(plastic 1630 年代形容词;plastics 塑料 1909 年贝克兰的酚醛树脂时代),plasma 是\"塑成之物\"(血浆 1845;等离子体是朗缪尔 1928),plastēs 塑造者,proto-plasm 原生质(1846),-plasty 成形术(rhino-plasty 隆鼻 1840 年代),plaster 是 em-plastron\"敷上的\"(古英语已借),plasticine 1897 商标,neo-plasm 新生物(肿瘤),plastid 质体,plastique 塑胶炸药。",
    "Greek plassein (to mould) may come from PIE *pelh₂- (to spread, flat), perhaps kin to Latin planus. plastikos mouldable (plastic as an adjective 1630s; plastics the materials from 1909, Baekeland's bakelite age), plasma the moulded thing (blood plasma 1845; Langmuir's plasma 1928), plastēs a moulder, proto-plasm (1846), -plasty a shaping operation (rhino-plasty 1840s), plaster em-plastron, the thing laid on (borrowed already in Old English), plasticine the 1897 trade name, neo-plasm a new growth, plastid, plastique the explosive."],
  phag: ["希腊语 phagein(吃)来自印欧语 *bʰag-(分、分得一份),同根有梵语 bhajati(分配)、bhaga(份、神——Bhagavad 薄伽梵!)、古教会斯拉夫语 bogŭ(神——俄语 bog!)——吃是\"分得的份\"。sarko-phagos 是\"吃肉\"的石灰石棺(普林尼说它 40 天化尸;sarcophagus),anthropo-phagos 食人(anthropophagi 莎士比亚),oeso-phagus 食道(\"送食物的\"),phago-cyte 吞噬细胞(梅契尼科夫 1884),bacterio-phage 噬菌体(1917),dys-phagia 吞咽困难,coprophagy,phagocytosis,-phagous(xylophagous 食木)。",
    "Greek phagein (to eat) comes from PIE *bʰag- (to share out, get a share), shared with Sanskrit bhajati (distributes), bhaga (a share, a god — Bhagavad!), Old Church Slavonic bogŭ (god — Russian bog!) — eating is one's portion. sarko-phagos the flesh-eating limestone coffin (Pliny said it consumed a body in forty days; sarcophagus), anthropo-phagos man-eating (Shakespeare's anthropophagi), oeso-phagus the food-carrier, phago-cyte the devouring cell (Metchnikoff 1884), bacterio-phage (1917), dys-phagia, coprophagy, -phagous (xylophagous wood-eating)."],
  sphere: ["希腊语 sphaira(球、玩的球)词源不明。毕达哥拉斯派说天体是 sphairai——\"天球音乐\";sphere 1300 年代(经法语 espere),hemi-sphere 半球,atmo-sphere 是 1630 年代造的\"蒸汽球\"(atmos 蒸汽),strato-sphere 1908,bio-sphere 1875(修斯),spherical 1520 年代,spheroid,litho-sphere,ionosphere 1926,blogosphere 1999,sfera 意大利语,esfera 西班牙语,sphère 法语。",
    "Greek sphaira (a ball, a playing-ball) is of unknown origin. The Pythagoreans made the heavens sphairai — the music of the spheres; sphere 1300s (through French espere), hemi-sphere, atmo-sphere a 1630s coinage, the ball of vapour (atmos), strato-sphere 1908, bio-sphere 1875 (Suess), spherical 1520s, spheroid, litho-sphere, ionosphere 1926, blogosphere 1999, Italian sfera, Spanish esfera, French sphère."],
  fum: ["fumus(烟)来自印欧语 *dʰuh₂-mós(烟),同根有希腊语 thymos(激情——\"冒烟的\"心)、thyein(献祭——烧)、梵语 dhūma(烟)、英语 dust?(存疑)、俄语 dym、立陶宛语 dūmai。罗马人 fumus 是烟(fumum vendere 卖烟——空许诺);fumare 冒烟——fumer 法语抽烟、fumare 意大利语、fumar 西班牙语,fumigare 熏(fumigate),per-fumare 熏透——香水(perfume 1530 年代经意大利语 profumo),fume 1400 年代,fumarole 火山气孔,fumet 野味的香气,fumier 法语粪堆(冒热气的),thyme 百里香是希腊线(熏香)。",
    "fumus (smoke) comes from PIE *dʰuh₂-mós (smoke), shared with Greek thymos (spirit — the smoking heart), thyein (to sacrifice — to burn), Sanskrit dhūma (smoke), Russian dym, Lithuanian dūmai. Roman fumus was smoke (fumum vendere, to sell smoke — empty promises); fumare to smoke — French fumer, Italian fumare, Spanish fumar, fumigare to smoke out (fumigate), per-fumare to smoke through — perfume (1530s via Italian profumo), fume 1400s, fumarole a volcanic vent, fumet the scent of game, French fumier a steaming dunghill; thyme is the Greek line's burnt offering."],
  gymn: ["希腊语 gymnos(裸)来自印欧语 *nogʷ-(裸)的换位——与拉丁语 nudus、英语 naked、德语 nackt、梵语 nagna 同根。希腊人裸体运动:gymnazein 裸体训练,gymnasion 体育场——也是哲学家讲学处(柏拉图的学园在 Akadēmeia 体育场),德语 Gymnasium 是文理中学(1500 年代人文主义借用),英语 gymnasium 是体育馆(1590 年代),gymnastics,gymno-sperm 裸子植物(种子不包在果里,1830 年代),gymno-sophists 印度的\"裸智者\"(亚历山大所见),gym 1871。",
    "Greek gymnos (naked) is PIE *nogʷ- (naked) with its sounds transposed — kin to Latin nudus, English naked, German nackt, Sanskrit nagna. Greeks exercised naked: gymnazein to train, gymnasion the training-ground — where philosophers also taught (Plato's Academy was a gymnasion), German Gymnasium the classical secondary school (a humanist borrowing of the 1500s), English gymnasium the sports hall (1590s), gymnastics, gymno-sperm the naked-seeded plants (1830s), the gymno-sophists Alexander's naked sages of India, gym 1871."],
  dendr: ["希腊语 dendron(树)是 *der-drew- 重叠——印欧语 *deru-(树、坚实),与英语 tree、tar、true(\"像树一样牢\")、德语 Teer、梵语 dāru、拉丁语 durus(硬)同根。rhodo-dendron 玫瑰树(杜鹃),dendrite 树突(神经元的分枝 1890 年代;也是矿物的树状结晶),dendro-chronology 树轮年代学(道格拉斯 1928),dendro-logy,philo-dendron 爱树的(攀缘),dendriform,Dendrobium 石斛(\"树上生活\")。",
    "Greek dendron (a tree) is a reduplicated *der-drew- — PIE *deru- (tree, firm), kin to English tree, tar, true (firm as a tree), German Teer, Sanskrit dāru, Latin durus (hard). rhodo-dendron the rose-tree, dendrite the branching of a neuron (1890s; also a tree-shaped crystal), dendro-chronology tree-ring dating (Douglass 1928), dendro-logy, philo-dendron the tree-loving climber, dendriform, Dendrobium the tree-dwelling orchid."],
  ethn: ["希腊语 ethnos(民族、群)可能来自印欧语 *swedʰ-no-(自己的一群),与 ēthos(习俗)同根。荷马的 ethnos 是一群人或兽;七十士译本用 ta ethnē 译希伯来语 goyim\"外邦人\"——所以 ethnikos 在教会拉丁语里是\"异教徒\"(ethnic 1375 年代先指异教!,1850 年代转为\"族群的\"),ethno-graphia 民族志(1830 年代),ethno-logia 1830 年代,ethnicity 1950 年代,ethno-centric 萨姆纳 1906,ethnarch 族长(希律家族的头衔),ethnie 法语族群,etnia 西班牙语。",
    "Greek ethnos (a nation, a band) may come from PIE *swedʰ-no- (one's own group), kin to ēthos (custom). Homer's ethnos was a company of men or beasts; the Septuagint used ta ethnē for Hebrew goyim, the Gentiles — so ethnikos in Church Latin meant heathen (ethnic meant pagan in the 1370s! and turned to peoples in the 1850s), ethno-graphia (1830s), ethno-logia 1830s, ethnicity 1950s, ethno-centric Sumner 1906, ethnarch (a title of the Herods), French ethnie, Spanish etnia."],
  oste: ["希腊语 osteon(骨)来自印欧语 *h₃ost-(骨),与拉丁语 os(ossis——ossify 骨化、osseous)、梵语 asthi、赫梯语 hastai、亚美尼亚语 oskr 同根;英语 bone 是另一个词。oste-itis 骨炎,osteo-porosis 骨质疏松(1840 年代),osteo-pathy 整骨疗法(斯蒂尔 1874),osteo-logy,osteo-blast 成骨细胞,peri-osteum 骨膜,osteo-arthritis,teleost 硬骨鱼,ossuary 是拉丁线的藏骨堂,ossobuco 意大利语\"带孔的骨\"。",
    "Greek osteon (bone) comes from PIE *h₃ost- (bone), one root with Latin os (ossis — ossify, osseous), Sanskrit asthi, Hittite hastai, Armenian oskr; English bone is a different word. oste-itis, osteo-porosis (1840s), osteo-pathy (Still 1874), osteo-logy, osteo-blast the bone-forming cell, peri-osteum, osteo-arthritis, teleost the bony fishes, ossuary the Latin line's bone-house, ossobuco Italian bone-with-a-hole."],
  spor: ["希腊语 spora(播种、种子)来自 speirein(撒),印欧语 *sper-(撒),与拉丁语 spargere、英语 sprout、spread?(存疑)同根。sporas 撒开的(sporadic 1650 年代——零星的),dia-spora 撒开——犹太人的离散(七十士译本申命记 28:25;1876 年英语),spore 孢子(1830 年代),sporo-phyte 孢子体,sperma 精液、种子(sperm),spermato-zoon 精子\"种子动物\"(1836),endo-spore,angio-sperm 被子植物,sporangium 孢子囊。",
    "Greek spora (a sowing, seed) comes from speirein (to scatter), PIE *sper- (to strew), kin to Latin spargere and English sprout. sporas scattered (sporadic 1650s), dia-spora a scattering — the Jewish dispersion (Septuagint Deuteronomy 28:25; English 1876), spore (1830s), sporo-phyte, sperma seed (sperm), spermato-zoon the seed-animal (1836), endo-spore, angio-sperm the vessel-seeded plants, sporangium."],
  ax: ["axis(轴)来自印欧语 *h₂eḱs-(轴),同根有希腊语 axōn(axon 轴突)、梵语 akṣa、英语 axle(北欧语 öxull)、ax-tree、德语 Achse、俄语 os'、拉丁语 ala(翅膀——*aks-la 肩)。罗马人 axis 是车轴、地轴、天轴;axialis 轴的(axial),ax-illa 腋窝(\"小翅\",axillary),Axis 轴心国是墨索里尼 1936 年的 asse Roma-Berlino,axle 是它的日耳曼亲戚,essieu 法语轴,eje 西班牙语,asse 意大利语,axiom 无关(axios 值得)。",
    "axis (an axle) comes from PIE *h₂eḱs- (axle), shared with Greek axōn (axon), Sanskrit akṣa, English axle (Norse öxull), ax-tree, German Achse, Russian os', Latin ala (a wing — *aks-la, the shoulder). Roman axis was the axle, the earth's axis, the pole of the sky; axialis (axial), ax-illa the armpit (a little wing; axillary), the Axis powers Mussolini's 1936 asse Roma-Berlino, axle the Germanic cousin, French essieu, Spanish eje, Italian asse; axiom is unrelated (axios, worthy)."],
  pyr: ["希腊语 pyr(火,属格 pyros)来自印欧语 *péh₂wr̥(火——\"无生命的火\",与 *h₁n̥gʷnis 有生命的火 ignis 相对),同根有英语 fire、德语 Feuer、赫梯语 paḫḫur、亚美尼亚语 hur、翁布里亚语 pir。pyra 火堆——pyre 火葬堆(1650 年代),pyro-technia 火技(pyrotechnics 烟火 1720 年代),pyro-mania 纵火狂(1840),pyrites 打火石(黄铁矿),pyrex 是 1915 年康宁的耐热玻璃(pie+rex?或 pyr),em-pyreal 最高天(火天),pyrrhic 无关(皮洛士),Pyrenees 无关?(存疑),pyro-lysis 热解,anti-pyretic 退烧,pyrosis 烧心,fire 是它的日耳曼亲戚。",
    "Greek pyr (fire, genitive pyros) comes from PIE *péh₂wr̥ (fire as a thing, against *h₁n̥gʷnis, fire as a living force — ignis), shared with English fire, German Feuer, Hittite paḫḫur, Armenian hur, Umbrian pir. pyra a fire-heap — pyre (1650s), pyro-technia the art of fire (pyrotechnics 1720s), pyro-mania (1840), pyrites the fire-striking stone, Pyrex Corning's 1915 glass, em-pyreal the highest, fiery heaven, pyro-lysis, anti-pyretic, pyrosis heartburn; fire is the Germanic cousin."],
  techn: ["希腊语 tekhnē(技艺)来自印欧语 *teḱs-(编织、建造),与拉丁语 texere(织——text、textile)、tignum(木料)、梵语 takṣan(木匠)、德语 Dachs?否、英语 无同根。柏拉图区分 tekhnē(可教的技艺)与 empeiria(经验);tekhnikos 技艺的(technical 1610 年代),tekhno-logia 是 1610 年代造的\"技艺之学\"(1850 年代指工业技术),technique 1817 经法语,poly-technic 1800 年代(巴黎综合理工 1794),techno 音乐 1988(底特律),technocracy 1919,Technik 德语,tectonic 是 tektōn 木匠(architect 首匠)。",
    "Greek tekhnē (craft, art) comes from PIE *teḱs- (to weave, to build), kin to Latin texere (to weave — text, textile), tignum (a beam), Sanskrit takṣan (a carpenter). Plato set tekhnē, a teachable craft, against empeiria, mere knack; tekhnikos (technical 1610s), tekhno-logia a 1610s coinage for the study of the arts (industrial by the 1850s), technique 1817 via French, poly-technic 1800s (the Paris École polytechnique 1794), techno music 1988 (Detroit), technocracy 1919, German Technik, tectonic from tektōn, a builder (architect the chief builder)."],
  mech: ["希腊语 mēkhanē(装置、计谋)来自 mēkhos(手段),印欧语 *magʰ-(能够)——与英语 may、might、德语 Macht、machen?(存疑)、俄语 moč' 同根!舞台的 mēkhanē 吊下神像(deus ex machina 机械降神);拉丁语 machina 机器,mēkhanikos 机械的(mechanic 1380 年代),machination 阴谋(\"装置\"),machine 1540 年代经法语,mechanism 1660 年代,machinery,mécanique,macchina 意大利语(也指汽车!),máquina 西班牙语,Maschine 德语(经法语),mechatronics 1969。",
    "Greek mēkhanē (a device, a contrivance) comes from mēkhos (a means), PIE *magʰ- (to be able) — one root with English may, might, German Macht, Russian moč'! The theatre's mēkhanē lowered gods onto the stage (deus ex machina); Latin machina, mēkhanikos (mechanic 1380s), machination a contriving, machine 1540s via French, mechanism 1660s, machinery, French mécanique, Italian macchina (also a car!), Spanish máquina, German Maschine (through French), mechatronics 1969."],
  hypo: ["希腊语 hypo(在下)来自印欧语 *upo(下、上来),与拉丁语 sub(*(s)upo)、英语 up、德语 auf、梵语 upa 同一个词——\"下\"与\"上\"同源!hypo-thesis 放在下面的——假设(1590 年代),hypo-krisis 是演员\"从下面回答\"——表演→伪善(hypocrite 1200 年代),hypo-thēkē 押在下面(hypothec 抵押;法语 hypothèque),hypo-tenuse 张在下面的边(1570 年代),hypo-dermic 皮下(1860 年代),hypo-thermia,hypo-chondria 是肋下(古人以为忧郁生在肋下!),hypo-glycemia,hypo 是摄影的定影剂(hyposulphite 1830 年代)。",
    "Greek hypo (under) comes from PIE *upo (under, up from under), one word with Latin sub (*(s)upo), English up, German auf, Sanskrit upa — under and up are kin! hypo-thesis a placing under — a supposition (1590s), hypo-krisis the actor's answering from below — playing a part → hypocrisy (hypocrite 1200s), hypo-thēkē a pledge laid under (hypothec; French hypothèque a mortgage), hypo-tenuse the side stretched under (1570s), hypo-dermic (1860s), hypo-thermia, hypo-chondria beneath the ribs (where the ancients seated melancholy!), hypo-glycemia, hypo the photographer's fixer (hyposulphite 1830s)."],
  paleo: ["希腊语 palaios(古老)来自 palai(很久以前),印欧语 *kʷel-(远)存疑——与 tēle(远)可能同根。palaeo- 是 19 世纪科学的前缀:palaeonto-logia 古生物学(布兰维尔 1822),Palaeo-lithic 旧石器(卢伯克 1865),Palaeo-zoic 古生代(塞奇威克 1838),palaeo-graphy 古文字学(1810 年代),palaeo-climate,Paleo diet 2000 年代,palaeo-botany;Palaiologos 是拜占庭末代王朝\"古言\"。",
    "Greek palaios (ancient) comes from palai (long ago), PIE *kʷel- (far) possible — perhaps kin to tēle (far). palaeo- is a prefix of 19th-century science: palaeonto-logia (Blainville 1822), Palaeo-lithic (Lubbock 1865), Palaeo-zoic (Sedgwick 1838), palaeo-graphy (1810s), palaeo-climate, the Paleo diet of the 2000s, palaeo-botany; Palaiologos was Byzantium's last dynasty, the old-word."],
  dys: ["希腊语 dys-(坏、难)来自印欧语 *dus-(坏),与梵语 dus-、阿维斯陀语 duš-、古爱尔兰语 do-、德语 zer-(!)、哥特语 tuz- 同根。它是 eu- 的反面:dys-enteria 坏肠(dysentery 1300 年代),dys-pepsia 消化不良(1700 年代),dys-lexia 1887(柏林),dys-topia 1868(穆勒),dys-function 1916,dys-trophy 营养不良,dys-phoria,Dys-nomia 无法(冥王星卫星),dys-praxia,muscular dystrophy 1860 年代。",
    "Greek dys- (bad, hard) comes from PIE *dus- (bad), shared with Sanskrit dus-, Avestan duš-, Old Irish do-, German zer- (!), Gothic tuz-. It is the opposite of eu-: dys-enteria bad bowels (dysentery 1300s), dys-pepsia (1700s), dys-lexia 1887 (Berlin), dys-topia 1868 (Mill), dys-function 1916, dys-trophy ill-nourishment, dys-phoria, Dysnomia lawlessness (Eris' moon), dys-praxia, muscular dystrophy 1860s."],
  derm: ["希腊语 derma(皮,属格 dermatos)来自 derein(剥皮),印欧语 *der-(剥、撕),与英语 tear(撕)、德语 zerren、梵语 dṛṇāti(裂)同根。dermat-itis 皮炎,dermato-logia 1810 年代,epi-dermis 表皮(亚里士多德已用),hypo-dermic 皮下,pachy-derm 厚皮动物(居维叶 1797),taxi-dermy,dermis 真皮(1830 年代),ecto-derm/endo-derm 胚层,Echino-dermata 棘皮动物,dermal,derma 意大利语?否,tear 是它的日耳曼亲戚。",
    "Greek derma (skin, genitive dermatos) comes from derein (to flay), PIE *der- (to flay, tear), kin to English tear (to rip), German zerren, Sanskrit dṛṇāti (bursts). dermat-itis, dermato-logia 1810s, epi-dermis (Aristotle's word), hypo-dermic, pachy-derm the thick-skinned beasts (Cuvier 1797), taxi-dermy, dermis (1830s), ecto-derm and endo-derm, Echino-dermata the spiny-skinned; tear is the Germanic cousin."],
  neur: ["希腊语 neuron(筋、腱、弦)来自印欧语 *(s)neh₁-(纺、缝),与拉丁语 nervus(nerve 是同一个词的拉丁形)、nere(纺)、英语 needle、snood、德语 Schnur、Nadel 同根——神经先是\"筋\"。盖伦区分了神经与肌腱;neuro-logia 1680 年代(威利斯),neur-algia 1807,neur-osis 是卡伦 1776 年的\"神经病\"(后弗洛伊德的神经症),neuron 1891(瓦尔代尔),neuro-science 1963,neurotic 1870 年代,aponeurosis,neurotransmitter 1961,neural,nerve 是拉丁线。",
    "Greek neuron (a sinew, tendon, bowstring) comes from PIE *(s)neh₁- (to spin, sew), kin to Latin nervus (nerve is the same word in Latin shape), nere (to spin), English needle and snood, German Schnur, Nadel — a nerve was first a sinew. Galen separated nerves from tendons; neuro-logia 1680s (Willis), neur-algia 1807, neur-osis Cullen's 1776 disease of the nerves (later Freud's), neuron 1891 (Waldeyer), neuro-science 1963, neurotic 1870s, aponeurosis, neurotransmitter 1961, neural; nerve is the Latin line."],
  bibl: ["希腊语 biblion(纸卷、书)来自 byblos(纸莎草),而 byblos 来自腓尼基港口 Byblos(今黎巴嫩 Jbeil)——希腊人从那里进口埃及纸莎草!ta biblia\"那些书\"是犹太与基督教的圣典,拉丁语 Biblia 被当作单数——Bible(1300 年代经法语),biblio-thēkē 书库(bibliothèque 法语图书馆、Bibliothek 德语、biblioteca),biblio-graphia 书目(1670 年代),biblio-philos 爱书者,biblio-mania 1730 年代,biblical,Bibel 德语,bibliolatry 圣经崇拜。",
    "Greek biblion (a papyrus roll, a book) comes from byblos (papyrus), and byblos from the Phoenician port Byblos (Jbeil in Lebanon) — through which the Greeks imported Egyptian papyrus! ta biblia, the books, were the Jewish and Christian scriptures; Latin Biblia was taken as a singular — the Bible (1300s via French), biblio-thēkē a book-store (French bibliothèque, German Bibliothek, biblioteca), biblio-graphia (1670s), biblio-philos, biblio-mania 1730s, biblical, German Bibel, bibliolatry."],
  gam: ["希腊语 gamos(婚姻)来自 gamein(娶),印欧语 *ǵem-(娶、结亲)存疑,与拉丁语 gener(女婿)、梵语 jāmātar(女婿)同根。mono-gamia 一夫一妻(1610 年代),poly-gamia 1590 年代,bi-gamia 重婚(1200 年代教会法),gamete 是 1878 年施特拉斯布格造的\"配偶\"细胞(gametēs 丈夫、gametē 妻子),gamo-genesis,crypto-gam 隐花植物(林奈,\"隐婚\"),phanero-gam 显花,exo-gamy 族外婚(麦克伦南 1865),endo-gamy,gamophobia。",
    "Greek gamos (marriage) comes from gamein (to marry), PIE *ǵem- (to marry) possible, kin to Latin gener (a son-in-law), Sanskrit jāmātar. mono-gamia (1610s), poly-gamia 1590s, bi-gamia (canon law 1200s), gamete Strasburger's 1878 spouse-cell (gametēs a husband, gametē a wife), gamo-genesis, crypto-gam Linnaeus' plants of hidden marriage, phanero-gam the visible, exo-gamy (McLennan 1865), endo-gamy, gamophobia."],
  pneum: ["希腊语 pneuma(风、气息、精神)来自 pnein(吹),词源不明(拟声?)。斯多葛派的 pneuma 是贯穿宇宙的气;新约的 pneuma hagion 圣灵(pneumatology 圣灵论);pneumōn 是肺(\"呼吸者\"),pneumonia 肺炎(1600 年代),pneumatikos 气动的(pneumatic 1650 年代;pneumatic tyre 1845 汤姆森、1888 邓禄普),pneumo-thorax 气胸,pneumo-coccus 肺炎球菌,pneumatic drill,pneumatics 气体力学,pneumonic。",
    "Greek pneuma (wind, breath, spirit) comes from pnein (to blow), of unknown, perhaps imitative, origin. The Stoics' pneuma was the breath pervading the cosmos; the New Testament's pneuma hagion the Holy Spirit (pneumatology); pneumōn the lung (the breather), pneumonia (1600s), pneumatikos of air (pneumatic 1650s; the pneumatic tyre Thomson 1845, Dunlop 1888), pneumo-thorax, pneumo-coccus, pneumatic drill, pneumatics, pneumonic."],
  schiz: ["希腊语 skhizein(劈)来自印欧语 *skei-d-(劈),与拉丁语 scindere、英语 shed、德语 scheiden 同根。skhisma 裂缝——教会分裂(schism 1380 年代;1054 年东西教会大分裂),skhistos 可劈的——schist 片岩(1790 年代),schizo-phrenia 是布洛伊勒 1908 年的\"心智分裂\"(取代克雷佩林的早发性痴呆),schizoid 1925,skhedē 劈开的木片——schedule(scheda→schedula 纸条,1400 年代)!,schizo-carp 分果,Schism。",
    "Greek skhizein (to split) comes from PIE *skei-d- (to split), one root with Latin scindere, English shed, German scheiden. skhisma a cleft — a division of the Church (schism 1380s; the Great Schism of 1054), skhistos splittable — schist the rock (1790s), schizo-phrenia Bleuler's 1908 split mind (replacing Kraepelin's dementia praecox), schizoid 1925, skhedē a split slip of wood — schedule (scheda → schedula, a slip of paper, 1400s)!, schizo-carp a splitting fruit."],
  xen: ["希腊语 xenos(外人、客人、东道主)来自印欧语 *gʰostis(陌生人、客人)存疑——即拉丁语 hostis/hospes、英语 guest 的那个词。荷马的 xenia 是宾主之礼(宙斯 Xenios 保护客人);xeno-phobia 1900 年代,xeno-philia,xenon 是拉姆齐 1898 年的\"陌生\"气体,xeno-graft 异种移植,xeno-glossy 说未学过的语言,Xenophon 是\"外来的声音\",proxeny 是城邦的名誉领事,xenia 植物学的\"异花\"效应,pyroxene 无关?(火+陌生)。",
    "Greek xenos (a stranger, guest, host) may come from PIE *gʰostis (stranger, guest) — the word of Latin hostis/hospes and English guest. Homer's xenia was the code of guest-friendship (Zeus Xenios guarded guests); xeno-phobia 1900s, xeno-philia, xenon Ramsay's 1898 stranger gas, xeno-graft, xeno-glossy speaking an unlearned tongue, Xenophon the foreign voice, proxeny the city's honorary consulship, xenia in botany, pyroxene the stranger to fire."],
  nec: ["希腊语 nekros(尸体、死者)来自印欧语 *neḱ-(死),与拉丁语 nex(杀害——inter-necine 互相残杀、per-nicious 致命)、nocere(害——innocent、noxious)、梵语 naśyati(灭)、托斯卡语 näk 同根。nekro-polis 死者之城(necropolis 1819),nekro-manteia 召死者问卜(necromancy;中世纪误拼 nigromantia\"黑术\"),necrosis 坏死(1660 年代),necro-logy 讣告,nektar 是 nek-tar\"胜过死亡\"——神的饮料(nectar!nectarine 1610 年代),necrophilia 1892,Necronomicon 是洛夫克拉夫特造的。",
    "Greek nekros (a corpse, the dead) comes from PIE *neḱ- (to die), kin to Latin nex (slaughter — inter-necine, per-nicious), nocere (to harm — innocent, noxious), Sanskrit naśyati (perishes), Tocharian näk. nekro-polis the city of the dead (necropolis 1819), nekro-manteia divination by the dead (necromancy; the Middle Ages respelt it nigromantia, black art), necrosis (1660s), necro-logy the death-notices, nektar nek-tar, death-overcoming — the gods' drink (nectar!; nectarine 1610s), necrophilia 1892, the Necronomicon Lovecraft's invention."],
  venat: ["venari(打猎)来自印欧语 *wen-(渴望、追求)——与 Venus(欲望)、venia(恩惠)、英语 win、wish、German gewinnen、Wunsch 同根:打猎是追求猎物。罗马的 venatio 是竞技场的斗兽表演(斗猎);venator 猎人,venison 是 venatio 经法语 venaison——猎物的肉(1300 年代;先指任何猎物肉,后专指鹿肉),venatic,venery 打猎(与 venery 色欲同形不同源——Venus),venado 西班牙语鹿(\"猎物\"),Venator 猎户座旁的星名。",
    "venari (to hunt) comes from PIE *wen- (to desire, strive for) — one root with Venus (desire), venia (favour), English win and wish, German gewinnen, Wunsch: hunting is the pursuit of prey. Roman venatio was the arena's beast-hunt; venator a hunter, venison venatio through French venaison — the flesh of game (1300s; any game before it narrowed to deer), venatic, venery hunting (a homonym of venery, lust — Venus), Spanish venado a deer (the hunted one)."],
  hepat: ["希腊语 hēpar(肝,属格 hēpatos)来自印欧语 *yēkʷr̥(肝),与拉丁语 iecur、梵语 yakṛt、阿维斯陀语 yākarə、立陶宛语 jeknos 同根;英语 liver 是另一个词。古人以为肝是欲望之座、占卜之器(肝卜 hepatoscopy);hepat-itis 肝炎(1727),hepatic 1400 年代,hepato-logy,hepato-cyte 肝细胞,hepatica 獐耳细辛(叶如肝——以形补形),heparin 1918(从肝提取),hepato-toxic,Hepatitis B 1965。",
    "Greek hēpar (the liver, genitive hēpatos) comes from PIE *yēkʷr̥ (liver), kin to Latin iecur, Sanskrit yakṛt, Avestan yākarə, Lithuanian jeknos; English liver is another word. The ancients seated desire in the liver and read omens in it (hepatoscopy); hepat-itis (1727), hepatic 1400s, hepato-logy, hepato-cyte, hepatica the liver-leaved plant (the doctrine of signatures), heparin 1918 (first extracted from liver), hepato-toxic, Hepatitis B 1965."],
  hist: ["希腊语 histos(织布机的立柱、织物、桅杆)来自 histanai(立),印欧语 *steh₂-(站)——与拉丁语 stare、英语 stand 同根:织机是\"立着的\"。histo-logia 是 1819 年迈尔造的\"组织学\"(生物组织像织物),histamine 1910(组织胺),histo-genesis,histone 组蛋白(1884),histo-compatibility,histiocyte;historia 是另一个词(histōr 知道的人——history)。",
    "Greek histos (a loom's upright, a web, a mast) comes from histanai (to set up), PIE *steh₂- (to stand) — one root with Latin stare and English stand: the loom is the standing thing. histo-logia is Mayer's 1819 coinage for the study of tissues (tissue being a web), histamine 1910, histo-genesis, histone (1884), histo-compatibility, histiocyte; historia is another word (histōr, one who knows — history)."],
  lip: ["希腊语 lipos(脂肪)来自印欧语 *leip-(粘、涂油),与梵语 limpati(涂)、英语 life、live、leave(\"留下\"→粘住)、德语 bleiben、Leib(身体)、俄语 lipnut'(粘)同根!lipid 1925(法语 lipide),lipo-suction 1983,lipo-protein,lipase 脂肪酶,lip-oma 脂肪瘤,lipo-philic 亲脂的,liposome 1968,lipaemia,lipid bilayer;lip(嘴唇)是另一个词(labium)。",
    "Greek lipos (fat) comes from PIE *leip- (to stick, smear with fat), kin to Sanskrit limpati (smears), English life, live, leave (to remain → to cling), German bleiben, Leib (the body), Russian lipnut' (to stick)! lipid 1925 (French lipide), lipo-suction 1983, lipo-protein, lipase, lip-oma, lipo-philic, liposome 1968, lipaemia; lip the mouth's is another word (labium)."],
  phyt: ["希腊语 phyton(植物)来自 phyein(生长、产生),印欧语 *bʰuH-(存在、生长)——与拉丁语 fui(我曾是)、futurus(将来的)、英语 be、been、德语 bauen(建——古义\"居住\")、Bauer、梵语 bhavati(是)同根!physis 自然是\"生长\"(phys-),phyton 植物是\"长出的\";neo-phyte 新栽的——新信徒(提摩太前书;1400 年代),phyto-plankton,phyto-logia,sapro-phyte 腐生植物,epi-phyte 附生植物,phyto-chemistry,zoo-phyte 植形动物,phylum 无关(phylē 部落)。",
    "Greek phyton (a plant) comes from phyein (to grow, bring forth), PIE *bʰuH- (to be, grow) — one root with Latin fui (I was), futurus, English be and been, German bauen (to build — once to dwell), Bauer, Sanskrit bhavati (is)! physis, nature, is growth (phys-), a phyton the thing grown; neo-phyte newly planted — a new convert (1 Timothy; 1400s), phyto-plankton, phyto-logia, sapro-phyte, epi-phyte, phyto-chemistry, zoo-phyte; phylum is unrelated (phylē, a tribe)."],
  plut: ["希腊语 ploutos(财富)来自 *plou-(满、流),与 plein(航行)、拉丁语 pluere、英语 flow 同根——财富是\"涌流\"。Ploutos 是财神(阿里斯托芬的喜剧《财神》让他复明),Ploutōn 是冥王——\"富者\"(地下藏矿藏和种子;Pluto,罗马的 Dis 也是\"富\"),pluto-cracy 富人统治(1650 年代),plutonium 是 1941 年西博格从冥王星命名的(接铀、镎),Plutarch 是\"财富之首\",plutonic 深成岩(冥府的火),plutolatry 拜金。",
    "Greek ploutos (wealth) comes from *plou- (full, flowing), kin to plein (to sail), Latin pluere, English flow — wealth is what flows in. Ploutos was the god of wealth (Aristophanes' comedy restores his sight), Ploutōn the underworld king — the Rich One (ore and seed lie underground; Pluto; Rome's Dis is also \"rich\"), pluto-cracy (1650s), plutonium Seaborg's 1941 name after the planet Pluto (following uranium, neptunium), Plutarch wealth-ruler, plutonic rock (the fire of the underworld), plutolatry."],
  rhin: ["希腊语 rhis(鼻,属格 rhinos)词源不明。rhino-keros 鼻角兽(rhinoceros,1300 年代),rhin-itis 鼻炎,rhino-plasty 隆鼻(1840 年代;印度古代已有鼻再造术),rhino-virus 1960 年代(感冒),oto-rhino-laryngology 耳鼻喉科,rhinal,rhino 是 rhinoceros 的缩略(1880 年代;英国俚语的\"钱\"另有来源),Rhine 无关(凯尔特语 Rēnos)。",
    "Greek rhis (the nose, genitive rhinos) is of unknown origin. rhino-keros the nose-horned beast (rhinoceros, 1300s), rhin-itis, rhino-plasty (1840s; ancient India already rebuilt noses), rhino-virus 1960s, oto-rhino-laryngology, rhinal, rhino the clipped rhinoceros (1880s); the Rhine is unrelated (Celtic Rēnos)."],
  sarc: ["希腊语 sarx(肉,属格 sarkos)来自印欧语 *twerḱ-(切)存疑,与阿维斯陀语 θwarəs-(切)可能同根——肉是切下的。sarko-phagos 食肉石棺,sarkasmos 是\"撕肉\"——冷嘲(sarcasm 1570 年代:sarkazein 咬牙切齿地说),sark-oma 肉瘤(1650 年代),sarco-mere 肌节,sarco-plasm,sarcoidosis,sarcous,sarco-penia 肌少症(1988),sarcophagus,sarcastic 1690 年代。",
    "Greek sarx (flesh, genitive sarkos) may come from PIE *twerḱ- (to cut), with Avestan θwarəs- (to cut) a possible cousin — flesh is what is cut. sarko-phagos the flesh-eating coffin, sarkasmos a tearing of flesh — a sneer (sarcasm 1570s: sarkazein, to speak with bared teeth), sark-oma a fleshy tumour (1650s), sarco-mere, sarco-plasm, sarcoidosis, sarco-penia (1988), sarcastic 1690s."],
  scler: ["希腊语 sklēros(硬)来自 skellein(晒干),印欧语 *(s)kel-(干、枯)存疑,与英语 shallow?否、古挪威语 skjallr(响亮)。sklērōsis 变硬——sclerosis(1400 年代医学),arterio-sclerosis 1886,multiple sclerosis 1870 年代,sclera 巩膜(眼的硬壳),sclero-derma 硬皮病,sclero-therapy,otosclerosis,sclerotic,Sclerophyll 硬叶植物。",
    "Greek sklēros (hard) comes from skellein (to dry up), PIE *(s)kel- (dry, parched) possible. sklērōsis a hardening — sclerosis (medical 1400s), arterio-sclerosis 1886, multiple sclerosis 1870s, the sclera the eye's hard coat, sclero-derma hard skin, sclero-therapy, otosclerosis, sclerotic, sclerophyll the hard-leaved plants."],
  som: ["希腊语 sōma(身体,属格 sōmatos)词源不明——可能来自 *twō-mn̥(肿胀)。荷马的 sōma 只指尸体,后指活体(与 psychē 相对);sōmatikos 身体的(somatic 1770 年代),psycho-somatic 1938,chromo-some 1888,soma 是赫胥黎《美丽新世界》的药(1932,借吠陀的 soma——另一个词),somato-type 体型(谢尔顿 1940),somato-statin 1973,somatic cell,ribo-some 1958,lyso-some 1955。",
    "Greek sōma (the body, genitive sōmatos) is of unknown origin — perhaps *twō-mn̥ (a swelling). Homer's sōma was only a corpse; later the living body, against psychē; sōmatikos (somatic 1770s), psycho-somatic 1938, chromo-some 1888, soma the drug of Huxley's Brave New World (1932, taking the Vedic soma — a different word), somato-type (Sheldon 1940), somato-statin 1973, ribo-some 1958, lyso-some 1955."],
  stereo: ["希腊语 stereos(坚固、立体)来自印欧语 *ster-(硬),与英语 stare(瞪——僵硬)、stern、starve(古义\"变僵\"→死)、德语 starr、sterben(死)、立陶宛语 starinti 同根。stereo-metria 立体测量(1570 年代),stereo-scope 是惠斯通 1838 年的\"立体镜\",stereo-type 是迪多 1798 年的\"固定版\"铅版印刷——1922 年李普曼借为\"刻板印象\",stereo-phonic 1927(stereo 1954 缩略),chole-sterol 胆汁的固体(1894),stereo-chemistry,stereo-isomer,stereotypical。",
    "Greek stereos (solid, firm) comes from PIE *ster- (stiff), kin to English stare (to look stiffly), stern, starve (once to grow stiff → to die), German starr, sterben (to die), Lithuanian starinti. stereo-metria solid geometry (1570s), stereo-scope Wheatstone's 1838 solid-viewer, stereo-type Didot's 1798 fixed printing plate — borrowed by Lippmann in 1922 for the fixed mental image, stereo-phonic 1927 (stereo 1954), chole-sterol the bile-solid (1894), stereo-chemistry, stereo-isomer, stereotypical."],
  therio: ["希腊语 thēr(野兽,属格 thēros)来自印欧语 *ǵʰwer-(野兽),与拉丁语 ferus(野——fierce、feral)、立陶宛语 žvėris、俄语 zver' 同根。thēriakē 是解兽毒的药——theriac 万灵药(米特拉达梯的解毒剂;treacle 是它经法语!——先指解毒糖浆,后指糖蜜),thērion 小兽——thērio-morphos 兽形的,thērio-logy,Megatherium 大地懒(居维叶 1796\"大兽\"),Dinotherium,therapsid 兽孔类,theropod 兽脚类(1881);fierce 是拉丁线。",
    "Greek thēr (a wild beast, genitive thēros) comes from PIE *ǵʰwer- (wild beast), kin to Latin ferus (wild — fierce, feral), Lithuanian žvėris, Russian zver'. thēriakē was the antidote to beast-bites — theriac, the cure-all (Mithridates' antidote; treacle is theriac through French! — an antidote-syrup before it was molasses), thērion a little beast — thērio-morphos beast-shaped, thērio-logy, Megatherium Cuvier's 1796 great beast, Dinotherium, therapsid, theropod (1881); fierce is the Latin line."],
  pleb: ["plebs(平民)来自印欧语 *pleh₁-(满)——与 plenus、plēthos(希腊语\"群众\")、英语 full 同根:平民是\"众多的\"。罗马的 plebs 是贵族(patricii)之外的公民;前 494 年平民撤离建立保民官(tribunus plebis),plebiscitum 是平民会决议(plebiscite 1530 年代;拿破仑三世的公投使它流行),plebeius 平民的(plebeian 1530 年代),pleb 1850 年代学生俚语(西点军校的新生),plebe,plèbe 法语,plebe 意大利语。",
    "plebs (the commons) comes from PIE *pleh₁- (full) — kin to plenus, Greek plēthos (a multitude), English full: the commons are the many. Rome's plebs were the citizens outside the patrician clans; their secession of 494 BC won the tribunus plebis, and a plebiscitum was a resolution of the plebeian assembly (plebiscite 1530s; Napoleon III's votes made it current), plebeius (plebeian 1530s), pleb 1850s student slang (a West Point freshman), plebe, French plèbe, Italian plebe."],
  post: ["post(在后)来自印欧语 *pos(在后、旁),同根有希腊语 无、立陶宛语 pas(在旁)、阿尔巴尼亚语 pas(后)。罗马人 post 是空间与时间的\"后\":post meridiem 午后(p.m.),post-scriptum 后记(P.S.),post-ponere 放在后面(postpone 1490 年代),posterus 后来的(posterity 后代,posterior 后部),post-humus 是 postumus\"最后的\"被误解为\"入土(humus)之后\"——遗腹的(posthumous),post-mortem 死后,post-modern 1949,preposterous 是\"前后颠倒\"(prae-posterus),postern 后门,post 邮政是另一个词(posita 驿站——放置)。",
    "post (after) comes from PIE *pos (after, beside), shared with Lithuanian pas (beside), Albanian pas (after). Roman post was after in place and time: post meridiem (p.m.), post-scriptum (P.S.), post-ponere to put after (postpone 1490s), posterus coming after (posterity, posterior), post-humus a misreading of postumus, last-born, as after-burial (posthumous), post-mortem, post-modern 1949, preposterous the back-to-front (prae-posterus), postern the back gate; the post that carries mail is another word (posita, a relay-station)."],
  extra: ["extra(在外)是 exterus(外面的)的阴性夺格——ex(出)的比较级;同根有 exterior、extremus(最外——extreme)、英语 无。罗马人 extra 是\"在…之外\"(extra ordinem 破格——extraordinary 1400 年代);extra-neus 外来的——strange 是它经法语 estrange(1300 年代;stranger、estrange 疏远),extra-vagari 游到界外(extravagant),extra-terrestrial 1860 年代,extra-vert 是荣格 1916 年的(后拼 extrovert),extra 独用是 1650 年代的\"额外\"(extraordinary 的缩略),extras 群众演员 1770 年代,étranger 法语外国人,extraño 西班牙语奇怪,estraneo 意大利语无关的。",
    "extra (outside) is the feminine ablative of exterus (outer) — the comparative of ex (out); kin to exterior and extremus (outermost — extreme). Roman extra was beyond (extra ordinem, out of the usual order — extraordinary 1400s); extra-neus from outside — strange is it through French estrange (1300s; stranger, estrange), extra-vagari to roam beyond bounds (extravagant), extra-terrestrial 1860s, extra-vert Jung's 1916 (later extrovert), extra alone from the 1650s as a clipped extraordinary, extras the crowd-players 1770s, French étranger a foreigner, Spanish extraño strange, Italian estraneo unrelated."],
  semi: ["semi-(半)来自印欧语 *sēmi-(半),与希腊语 hēmi-(hemisphere)、梵语 sāmi、古英语 sām-(sam-blind 半瞎——莎士比亚的 sand-blind!)、古高地德语 sāmi- 同根。罗马人 semi-: semi-circulus 半圆,semi-vocalis 半元音,semi-deus 半神,semi-uncia 半盎司,semis 半个 as;semi-colon 1640 年代,semi-final 1880 年代,semi-conductor 1838,semi-tone 半音,semi-detached 半独立式(1859),sesqui- 是 semis-que\"再加一半\"(sesquicentennial 150 年),demi- 是 dimidius 经法语(demi-god、demitasse),hemi- 是希腊线。",
    "semi- (half) comes from PIE *sēmi- (half), shared with Greek hēmi- (hemisphere), Sanskrit sāmi, Old English sām- (sam-blind, half-blind — Shakespeare's sand-blind!), Old High German sāmi-. Roman semi-: semi-circulus, semi-vocalis a semi-vowel, semi-deus a demigod, semi-uncia half an ounce, semis half an as; semi-colon 1640s, semi-final 1880s, semi-conductor 1838, semi-tone, semi-detached (1859), sesqui- semis-que, and a half again (sesquicentennial), demi- dimidius through French (demi-god, demitasse), hemi- the Greek line."],
  hol: ["希腊语 holos(全)来自印欧语 *solh₂-(全),与拉丁语 salvus、solidus、sollus、梵语 sarva 同根;英语 whole 是另一个词(*koilo-)。holo-kauston 全烧的祭(holocaust 1200 年代指燔祭,1950 年代专指纳粹屠杀),katholikos 按整体的——普世的(catholic;1054 年后西方教会自称),holo-graphia 全息(伽博 1947),holism 是斯马茨 1926 年造的\"整体论\",holo-graph 亲笔文件(全手写),holo-cene 全新世(1867),Holo-thuria 海参,hologram 1949。",
    "Greek holos (whole) comes from PIE *solh₂- (whole), kin to Latin salvus, solidus, sollus, Sanskrit sarva; English whole is another word (*koilo-). holo-kauston the wholly-burnt offering (holocaust meant a burnt sacrifice in the 1200s and the Nazi murder of the Jews by the 1950s), katholikos according to the whole — universal (catholic; the Western Church's name after 1054), holo-graphia whole-writing (Gabor 1947), holism Smuts' 1926 coinage, holo-graph a document wholly in the author's hand, Holo-cene the wholly recent epoch (1867), Holo-thuria the sea-cucumbers, hologram 1949."],
  bar: ["希腊语 barys(重)来自印欧语 *gʷerh₂-(重),与拉丁语 gravis(grave、gravity)、梵语 guru(重——上师!)、哥特语 kaurus、爱尔兰语 bair 同根。baros 重量:baro-meter 是 1660 年代玻意耳的\"重量计\"(气压计),bary-ton 重音——男中音(baritone 1600 年代经意大利语),barium 是戴维 1808 年从 baryta 重土命名的,bary-centre 重心,bary-on 重子(1953),iso-bar 等压线,hyper-baric 高压氧,baritone,brio?否,guru 是它的梵语亲戚。",
    "Greek barys (heavy) comes from PIE *gʷerh₂- (heavy), kin to Latin gravis (grave, gravity), Sanskrit guru (heavy — the guru!), Gothic kaurus, Irish bair. baros weight: baro-meter Boyle's 1660s weight-measurer of the air, bary-tonos heavy-toned — baritone (1600s via Italian), barium Davy's 1808 metal from baryta, heavy earth, bary-centre, bary-on (1953), iso-bar, hyper-baric; guru is the Sanskrit cousin."],
  arithm: ["希腊语 arithmos(数)来自印欧语 *h₂rei-(数、排列),与拉丁语 ritus(仪式——\"排好的\")、英语 rhyme(经拉丁语 rithmus 混淆)、read?否、古爱尔兰语 rím(数)、古英语 rīm(数)同根。arithmētikē (tekhnē) 数术——arithmetic 1250 年代(经法语 arismetique,中世纪误拼 ars metrica),logarithm 是纳皮尔 1614 年的\"比例数\",algorithm 是花拉子米的名字受 arithmos 影响的拼法!,arithmancy 数字占卜,arithmetician,Arithmetica 丢番图的书(费马在页边写下大定理)。",
    "Greek arithmos (number) comes from PIE *h₂rei- (to count, arrange), kin to Latin ritus (a rite — the thing set in order), Old Irish rím (a number), Old English rīm (number), and English rhyme (confused with Latin rithmus). arithmētikē (tekhnē) the art of number — arithmetic 1250s (via French arismetique, medieval respelt ars metrica), logarithm Napier's 1614 ratio-number, algorithm al-Khwarizmi's name respelt under arithmos!, arithmancy, arithmetician, the Arithmetica of Diophantus (in whose margin Fermat wrote his theorem)."],
  ichthy: ["希腊语 ikhthys(鱼)来自印欧语 *dʰǵʰu-(鱼),与亚美尼亚语 jukn、立陶宛语 žuvis、古普鲁士语 suckans 同根;拉丁语 piscis 是另一个词。ΙΧΘΥΣ 是早期基督徒的暗号——Iēsous Khristos Theou Yios Sōtēr\"耶稣基督神子救主\"的首字母,鱼形符号由此;ichthyo-logia 鱼类学(1640 年代),Ichthyo-saurus 鱼龙(柯尼希 1818),ichthy-osis 鱼鳞病,ichthyo-phagi 食鱼者(希罗多德),ichthyology。",
    "Greek ikhthys (a fish) comes from PIE *dʰǵʰu- (fish), kin to Armenian jukn, Lithuanian žuvis, Old Prussian suckans; Latin piscis is another word. ΙΧΘΥΣ was the early Christians' cipher — the initials of Iēsous Khristos Theou Yios Sōtēr, Jesus Christ Son of God Saviour, whence the fish symbol; ichthyo-logia (1640s), Ichthyo-saurus the fish-lizard (König 1818), ichthy-osis the fish-scale skin, the ichthyo-phagi fish-eaters of Herodotus."],
  pseudo: ["希腊语 pseudos(谎言)来自 pseudein(欺骗),词源不明。pseud-ōnymos 假名(pseudonym 1840 年代经法语),pseudo-prophētēs 假先知(新约),pseudepigrapha 伪托之书,pseudo- 作前缀在英语 15 世纪起(pseudo-science 1840 年代),pseudo-pod 伪足(1840 年代),pseudo-code,pseudo-random,pseudo 独用 1940 年代\"装模作样的人\",pseudocyesis 假孕,pseud 1960 年代英国俚语。",
    "Greek pseudos (a lie) comes from pseudein (to deceive), of unknown origin. pseud-ōnymos a false name (pseudonym 1840s via French), pseudo-prophētēs the false prophets of the New Testament, pseudepigrapha books under false names, pseudo- as an English prefix from the 15th century (pseudo-science 1840s), pseudo-pod the false foot (1840s), pseudo-code, pseudo-random, pseudo alone 1940s a pretender, pseudocyesis false pregnancy, pseud 1960s British slang."],
  rhiz: ["希腊语 rhiza(根)来自印欧语 *wreh₂d-(根、枝),与拉丁语 radix(radical、radish)、英语 root(北欧语 rót)、wort(草——古英语 wyrt)、德语 Wurzel 同根!rhizōma 根团——rhizome 根茎(1830 年代;德勒兹 1976 年借为哲学概念),rhizo-bium 根瘤菌,rhizo-sphere 根际(1904),rhizo-pod 根足虫,my-corrhiza 菌根(1885),glycyrrhiza 甘草\"甜根\"——liquorice!,radix 是它的拉丁亲戚。",
    "Greek rhiza (a root) comes from PIE *wreh₂d- (root, branch), one root with Latin radix (radical, radish), English root (Norse rót) and wort (Old English wyrt, a plant), German Wurzel! rhizōma a root-mass — rhizome (1830s; Deleuze's 1976 philosophical borrowing), rhizo-bium the root-nodule bacterium, rhizo-sphere (1904), rhizo-pod, my-corrhiza (1885), glycyrrhiza the sweet root — liquorice!; radix is the Latin cousin."],
  zym: ["希腊语 zymē(酵)来自印欧语 *yeue-(混合)存疑,与拉丁语 ius(汤汁——juice)、梵语 yūṣa(汤)可能同根。新约的 zymē 是酵(\"法利赛人的酵\";azymos 无酵饼——东西教会争论圣餐用不用酵),en-zymē 是屈内 1878 年造的\"在酵里\"——酶,zymo-logy 发酵学,-ase 是从 diastase(1833)截出的酶后缀(lipase、amylase),zymase 1897(布赫纳,无细胞发酵),zymurgy 酿造,azyme 无酵饼。",
    "Greek zymē (leaven) may come from PIE *yeue- (to blend), possibly kin to Latin ius (broth — juice), Sanskrit yūṣa (soup). The New Testament's zymē is leaven (the leaven of the Pharisees; azymos the unleavened bread — the East–West quarrel over the Eucharist), en-zymē Kühne's 1878 in-leaven — enzyme, zymo-logy, -ase the enzyme suffix cut from diastase (1833) (lipase, amylase), zymase 1897 (Buchner's cell-free fermentation), zymurgy the craft of brewing, azyme."],
  pleth: ["希腊语 plēthos(群众、充满)来自 pimplanai(填满),印欧语 *pleh₁-(满),与拉丁语 plenus、plebs、英语 full 同根。plēthōrē 是盖伦医学的\"多血\"——体液过剩(plethora 1540 年代医学;1700 年代转为\"过多\"),plethysmo-graph 体积描记器(1870 年代),plethoric,pleon-asm 是 pleon(更多)——冗言(1580 年代),pleio-tropy,Pliocene/Pleistocene 是 pleiōn/pleistos\"更多/最多(新种)\"(莱尔 1833/1839)。",
    "Greek plēthos (a multitude, fullness) comes from pimplanai (to fill), PIE *pleh₁- (full), kin to Latin plenus, plebs, English full. plēthōrē was Galenic medicine's excess of blood (plethora medical 1540s; overabundance by the 1700s), plethysmo-graph (1870s), plethoric, pleon-asm from pleon (more) — redundancy (1580s), pleio-tropy, Pliocene and Pleistocene pleiōn/pleistos, more and most (new species) (Lyell 1833, 1839)."],
  brady: ["希腊语 bradys(慢)来自印欧语 *gʷr̥d-(重、慢)存疑,与拉丁语 gurdus(笨)、拉脱维亚语 gurds(疲惫)可能同根。brady-cardia 心动过缓(1890),brady-kinesia 运动迟缓(帕金森病),brady-phrenia,brady-kinin 缓激肽(1949——使肠慢慢收缩),brady-pnoea 呼吸过缓,Bradypus 树懒(\"慢脚\");tachy- 是它的反面。",
    "Greek bradys (slow) may come from PIE *gʷr̥d- (heavy, slow), possibly kin to Latin gurdus (dull), Latvian gurds (weary). brady-cardia (1890), brady-kinesia the slowness of Parkinson's, brady-phrenia, brady-kinin (1949 — it makes gut muscle contract slowly), brady-pnoea, Bradypus the slow-footed sloth; tachy- is its opposite."],
  potam: ["希腊语 potamos(河)来自 *pet-(冲、飞)——\"冲下来的水\";与 piptein(落)、petesthai(飞)、拉丁语 petere 同根(存疑)。hippo-potamos 河马(希罗多德),Meso-potamia 两河之间(幼发拉底与底格里斯;希腊化时期的名字),potamo-logy 河流学,Potamogeton 眼子菜(\"河邻\"),potamic,Potamon 河蟹,potamo-plankton。",
    "Greek potamos (a river) comes from *pet- (to rush, to fly) — the rushing water; kin to piptein (to fall), petesthai (to fly), Latin petere (disputed). hippo-potamos the river-horse (Herodotus), Meso-potamia the land between the rivers Euphrates and Tigris (a Hellenistic name), potamo-logy, Potamogeton the pondweed (river-neighbour), potamic, Potamon the river-crab, potamo-plankton."],
  thalass: ["希腊语 thalassa(海)是前希腊(地中海底层语)借词——希腊人从北方来到海边,借了当地的词;荷马也用 hals(盐——海)、pontos、pelagos。色诺芬《长征记》的 Thalatta! Thalatta!\"海!海!\"(万人军望见黑海);thalasso-therapy 海水疗法(1867 法语),thalass-aemia 地中海贫血(1936——\"海血\"),Thalassa 是海的女神,thalasso-cracy 海权(米诺斯),thalassic,Panthalassa 泛大洋。",
    "Greek thalassa (the sea) is a pre-Greek loan — the Greeks came to the coast from inland and took the natives' word; Homer also says hals (salt — the sea), pontos, pelagos. Xenophon's Anabasis has the Ten Thousand's cry Thalatta! Thalatta! at the sight of the Black Sea; thalasso-therapy (French 1867), thalass-aemia the sea-blood anaemia of the Mediterranean (1936), Thalassa the sea-goddess, thalasso-cracy sea-power (Minoan), thalassic, Panthalassa the all-ocean."],
  pyret: ["希腊语 pyretos(发热)来自 pyr(火)——热病是身体里的火;印欧语 *péh₂wr̥。希波克拉底论 pyretoi;anti-pyretic 退热药(1680 年代),pyrexia 发热(1760 年代),pyreto-logy,pyreto-therapy 发热疗法(瓦格纳-尧雷格 1917 用疟疾治麻痹性痴呆,得 1927 年诺贝尔奖),hyper-pyrexia 超高热,pyretic。",
    "Greek pyretos (fever) comes from pyr (fire) — fever is fire in the body; PIE *péh₂wr̥. Hippocrates wrote on the pyretoi; anti-pyretic (1680s), pyrexia (1760s), pyreto-logy, pyreto-therapy fever-cure (Wagner-Jauregg's 1917 malaria treatment of paresis, Nobel 1927), hyper-pyrexia, pyretic."],
  nous: ["希腊语 nous/noos(心智)词源不明。阿那克萨戈拉说 nous 安排万物;亚里士多德的 nous 是理性直观,普罗提诺的 Nous 是太一之下的第二本体;noein 思考——noēma 思想(胡塞尔的 noema/noesis),noētikos(noetic 1650 年代),para-noia 是\"心智偏离\"(paranoia 1811 年医学,希腊语已有\"疯\"),meta-noia 悔改(\"心的转变\"——新约),pro-noia 天意,dia-noia 推理,nous 英国俚语\"常识\"(1700 年代,牛津),noo-sphere 心智圈(德日进 1920 年代),eu-noia 善意。",
    "Greek nous/noos (mind) is of unknown origin. Anaxagoras said nous ordered all things; Aristotle's nous is intuitive reason, Plotinus' Nous the second hypostasis below the One; noein to think — noēma a thought (Husserl's noema and noesis), noētikos (noetic 1650s), para-noia the mind beside itself (paranoia medical 1811, madness already in Greek), meta-noia a change of mind — repentance (the New Testament), pro-noia providence, dia-noia reasoning, nous British slang for common sense (1700s, Oxford), noo-sphere (Teilhard 1920s), eu-noia goodwill."],
  phys: ["希腊语 physis(自然)来自 phyein(生长),印欧语 *bʰuH-(存在、生长)——与拉丁语 fui、英语 be、德语 bauen 同根:自然是\"生长出来的\"。前苏格拉底哲人写 Peri physeōs《论自然》;亚里士多德的 Physika 是运动与变化之学(physics 1580 年代;Metaphysics 是\"排在物理学之后的书\"!),physikos 自然的——physician 是研究自然(医学)的人(1200 年代;physic 是药),physio-logia 1560 年代,physique 体格(1820 年代法语),physical 1590 年代,physio-therapy 1905,physicist 是惠威尔 1840 年造的,Physik 德语。",
    "Greek physis (nature) comes from phyein (to grow), PIE *bʰuH- (to be, grow) — kin to Latin fui, English be, German bauen: nature is what has grown. The pre-Socratics wrote Peri physeōs, On Nature; Aristotle's Physika is the science of motion and change (physics 1580s; the Metaphysics are the books shelved after the Physics!), physikos natural — a physician studies nature, i.e. medicine (1200s; physic a drug), physio-logia 1560s, physique (French 1820s), physical 1590s, physio-therapy 1905, physicist Whewell's 1840 coinage, German Physik."],
  mus: ["希腊语 Mousa(缪斯)可能来自印欧语 *men-(想)——\"使人记起者\"(存疑),或 *mont-(山)。九缪斯是记忆女神的女儿(赫西俄德列名);mouseion 是缪斯的圣所——亚历山大的 Mouseion 是托勒密的学术院(museum 1610 年代指学者的书房,1680 年代指藏品陈列——阿什莫尔博物馆 1683),mousikē (tekhnē) 缪斯的技艺——音乐(music 1250 年代;希腊的 mousikē 含诗与舞),musical,musée 法语,Museo 意大利语/西班牙语,museo-logy,mosaic 是 mouseion 经拉丁语 musivum\"缪斯的作品\"(镶嵌画)!,musette。",
    "Greek Mousa (a Muse) may come from PIE *men- (to think) — the reminder (disputed), or *mont- (a mountain). The nine Muses were daughters of Memory (Hesiod names them); a mouseion was their shrine — the Mouseion of Alexandria the Ptolemies' academy (museum meant a scholar's study in the 1610s and a collection on show by the 1680s — the Ashmolean 1683), mousikē (tekhnē) the Muses' art — music (1250s; Greek mousikē included poetry and dance), musical, French musée, Italian and Spanish museo, museo-logy, and mosaic is mouseion through Latin musivum, the Muses' work!, musette."],
  funct: ["fungi(履行、执行,分词 functus)来自印欧语 *bʰeug-(享用)存疑——与梵语 bhuṅkte(享用)可能同根。罗马人 fungi officio 履行职责,fungi vita 走完一生(defunctus 已死——defunct);functio 履行(function 1530 年代\"职务\"),functionalis,莱布尼茨 1673 年借 functio 为数学的\"函数\",functionary 官员(1790 年代法语 fonctionnaire),functionalism 建筑(1930 年代),perfunctory 是 per-fungi\"做完了事\"——敷衍(1580 年代),fonction 法语,funzione,función,dysfunction 1916。",
    "fungi (to perform, discharge, participle functus) may come from PIE *bʰeug- (to enjoy, use), possibly kin to Sanskrit bhuṅkte (enjoys). Romans fungi officio, performed a duty, fungi vita, finished a life (defunctus dead — defunct); functio performance (function 1530s, an office), functionalis, Leibniz borrowed functio in 1673 for the mathematical function, functionary (French fonctionnaire 1790s), functionalism in architecture (1930s), perfunctory per-fungi, got through — done carelessly (1580s), French fonction, Italian funzione, Spanish función, dysfunction 1916."],
  zone: ["希腊语 zōnē(腰带)来自 zōnnynai(束腰),印欧语 *yeh₃s-(束),与阿维斯陀语 yāsta(束腰的)、立陶宛语 juosta(带)、古教会斯拉夫语 pojasŭ 同根。希腊女人的 zōnē 是腰带(解带=结婚);天文学家把地球分成五个 zōnai\"带\"(热带、温带、寒带——巴门尼德),拉丁语 zona 腰带、地带(zone 1390 年代地理,1800 年代泛指区域),zonal,time zone 1880 年代,zoning 1912(纽约),Zone 德语(经法语),zona 意大利语/西班牙语区域,zoster 是希腊语另一词\"带\"——带状疱疹 herpes zoster。",
    "Greek zōnē (a girdle) comes from zōnnynai (to gird), PIE *yeh₃s- (to gird), kin to Avestan yāsta (girt), Lithuanian juosta (a belt), Old Church Slavonic pojasŭ. A Greek woman's zōnē was her girdle (loosed at marriage); astronomers cut the earth into five zōnai, belts (torrid, temperate, frigid — Parmenides), Latin zona a girdle, a belt of the earth (zone in geography 1390s, any district by the 1800s), zonal, time zone 1880s, zoning 1912 (New York), German Zone (via French), Italian and Spanish zona; zoster is the other Greek belt — herpes zoster."],
  charact: ["希腊语 kharaktēr(刻印的工具、印记)来自 kharassein(刻),词源不明(可能前希腊语)。kharaktēr 先是钱币的模具和印记,后指人的\"印记\"——性格(泰奥弗拉斯托斯《人物志》Kharaktēres 前 319 年);拉丁语 character 刻痕、字母,character 1300 年代英语先指\"符号\"(字符——computer character),1640 年代指性格,1660 年代指戏剧人物,characteristic 1660 年代,caractère 法语,Charakter 德语,carácter 西班牙语,carattere 意大利语(也指字体!),characterize 1590 年代。",
    "Greek kharaktēr (an engraving tool, a stamp) comes from kharassein (to engrave), of unknown, perhaps pre-Greek, origin. kharaktēr was first the die and the mark on a coin, then the stamp on a person — character (Theophrastus' Kharaktēres, 319 BC); Latin character a mark, a letter, character in English a symbol in the 1300s (the computer's character), a moral nature by the 1640s, a person in a play by the 1660s, characteristic 1660s, French caractère, German Charakter, Spanish carácter, Italian carattere (also a typeface!), characterize 1590s."],
  cuss: ["quatere(摇、打,分词 quassus)来自印欧语 *kʷeh₁t-(摇)存疑,与古教会斯拉夫语 无、威尔士语 无——孤立的拉丁词。复合词里变 -cutere:dis-cutere 打散——讨论(discuss 1300 年代先是\"驱散\",1450 年代\"讨论\"),per-cutere 打透(percussion 1400 年代;打击乐 1770 年代),con-cutere 一起摇(concussion 脑震荡),re-percutere 反弹(repercussion),ex-cutere 抖出(rescue 是 re-ex-cutere 经法语 rescourre!),quassare 频繁式——法语 casser 打碎(cashier 撤职、quash 撤销、squash 压扁 ex-quassare),succussion 震荡,Diskussion 德语。",
    "quatere (to shake, strike, participle quassus) may come from PIE *kʷeh₁t- (to shake) — an isolated Latin word. In compounds it becomes -cutere: dis-cutere to shake apart — discuss (to dispel in the 1300s, to debate by the 1450s), per-cutere to strike through (percussion 1400s; the instruments 1770s), con-cutere to shake together (concussion), re-percutere to strike back (repercussion), ex-cutere to shake out (rescue is re-ex-cutere through French rescourre!), the frequentative quassare — French casser to break (cashier, quash, squash from ex-quassare), succussion, German Diskussion."],
  arg: ["arguere(使清楚、证明、指责)来自 argus(明亮)——印欧语 *h₂erǵ-(白、亮),与 argentum(银——Argentina、argent)、希腊语 argos(亮白;Argos)、argyros(银)、梵语 rajata(银)、赫梯语 ḫarkiš(白)同根。罗马人 arguere 是把事情弄明;argumentum 证据、论证(argument 1300 年代——先指证据,后指争论),argutus 尖锐的、机敏的,ar-guere 也有\"控告\",argumentation,argumentative,Argument 德语(学术),argumento 西班牙语(也指剧情),argent 纹章的银,argue 1300 年代经法语 arguer。",
    "arguere (to make clear, prove, accuse) comes from argus (bright) — PIE *h₂erǵ- (white, shining), kin to argentum (silver — Argentina, argent), Greek argos (bright; Argos), argyros (silver), Sanskrit rajata (silver), Hittite ḫarkiš (white). Romans arguere made a matter clear; argumentum proof, a line of reasoning (argument 1300s — evidence before it was a quarrel), argutus sharp, quick-witted, argumentation, argumentative, German Argument, Spanish argumento (also a plot), argent heraldry's silver, argue 1300s through French arguer."],
  cancel: ["cancelli(格栅、栏杆)是 cancer(格子——与 carcer 牢笼异化?存疑)的指小复数。罗马法庭的 cancelli 是隔开法官与公众的栏杆;cancellarius 是站在栏杆边的书记——中世纪成了 chancellor(掌玺大臣、大学校长;德国的 Kanzler 总理),cancellare 用格线划掉——cancel(1400 年代),chancel 是教堂圣坛前的格栅区(1300 年代),chancery 大法官法庭(Chancery Lane),chancellery,Kanzlei 德语公署,cancellous bone 网状骨(格状),cancer 螃蟹是另一个词。",
    "cancelli (a lattice, railings) is the diminutive plural of cancer (a grid — perhaps carcer, a cage, dissimilated). In a Roman court the cancelli fenced the judges from the public; the cancellarius was the clerk at the bar — in the Middle Ages the chancellor (keeper of the seal, head of a university; Germany's Kanzler), cancellare to cross out with a lattice of lines — cancel (1400s), chancel the screened part of a church (1300s), Chancery the Lord Chancellor's court (Chancery Lane), chancellery, German Kanzlei an office, cancellous bone the lattice-work kind; cancer the crab is another word."],
});
